#!/usr/bin/env bash
# Kernel-checked proofs, over the Lean model formal/Bootstrap/X86Min.lean, that
# the two seed loaders reproduce themselves and each other:
#
#   seedA_self   exec seed-a on seed-a.hex  = exit 0, output seed-a
#   seedA_cross  exec seed-a on seed-b.hex  = exit 0, output seed-b
#   seedB_self   exec seed-b on seed-b.oct  = exit 0, output seed-b
#   seedB_cross  exec seed-b on seed-a.oct  = exit 0, output seed-a
#
# Each proof is generated by formal/Bootstrap/GenProof.lean as checkpoint
# lemmas (`decide +kernel`, chunks of $CHUNK steps) and checked by `lean`;
# nothing the generator prints is trusted. Cost, measured 2026-11-15: about
# 13 s and 2.6 GB per 1000-step chunk.
#
# It also checks the theorems about every listing, Bootstrap/SeedA.lean and
# Bootstrap/SeedB.lean (seedA_correct, seedA_refuses, seedB_correct,
# seedB_refuses), and that they rest on no axiom beyond propext,
# Classical.choice and Quot.sound. All six checks run in parallel. Then it builds
# Bootstrap/SeedUniBridge.lean (the same four theorems and the fault-free `prun` runs,
# lifted to X86Uni, accepting and refusing) and audits those eight theorems the same way.
#
#   bootstrap/model/seed_proofs.sh [outdir]
set -euo pipefail
root="$(cd "$(dirname "$0")/../.." && pwd)"
lean="${LEAN_BIN:+$LEAN_BIN/}lean"
chunk="${CHUNK:-1000}"
work="${1:-$(mktemp -d)}"
mkdir -p "$work"

"$root/bootstrap/model/build_model.sh" "$work/olean"
cd "$root/formal"
export LEAN_PATH="$work/olean"

proofs=("seedA_self seedA seedAHex seedA" "seedA_cross seedA seedBHex seedB"
        "seedB_self seedB seedBOct seedB" "seedB_cross seedB seedAOct seedA")
for p in "${proofs[@]}"; do
  set -- $p
  "$lean" --run Bootstrap/GenProof.lean "$1" "$2" "$3" "$4" "$chunk" > "$work/$1.lean"
done

pids=()
for p in "${proofs[@]}"; do
  set -- $p
  ( start=$(date +%s)
    if "$lean" "$work/$1.lean" > "$work/$1.log" 2>&1; then
      echo "PROOF_OK $1 $(( $(date +%s) - start ))s"
    else
      echo "PROOF_FAIL $1"; head -c 2000 "$work/$1.log"; exit 1
    fi ) &
  pids+=($!)
done
for m in SeedA SeedB; do
  ( start=$(date +%s)
    if "$lean" "Bootstrap/$m.lean" -o "$work/olean/Bootstrap/$m.olean" > "$work/$m.log" 2>&1; then
      echo "PROOF_OK $m $(( $(date +%s) - start ))s"
    else
      echo "PROOF_FAIL $m"; head -c 2000 "$work/$m.log"; exit 1
    fi ) &
  pids+=($!)
done
fail=0
for pid in "${pids[@]}"; do wait "$pid" || fail=1; done

# The same theorems lifted to the unified machine X86Uni (Bootstrap/SeedUniBridge.lean). It
# imports SeedA and SeedB, so it runs after them, with the X86Int side of the model first.
if [ "$fail" = 0 ]; then
  for m in PDist X86Env X86Int X86Dec X86Uni SeedUniBridge; do
    start=$(date +%s)
    if "$lean" "Bootstrap/$m.lean" -o "$work/olean/Bootstrap/$m.olean" > "$work/$m.log" 2>&1; then
      echo "PROOF_OK $m $(( $(date +%s) - start ))s"
    else
      echo "PROOF_FAIL $m"; head -c 2000 "$work/$m.log"; fail=1; break
    fi
  done
fi

if [ "$fail" = 0 ]; then
  printf '%s\n' 'import Bootstrap.SeedA' 'import Bootstrap.SeedB' 'import Bootstrap.SeedUniBridge' \
    '#print axioms X86Min.SeedA.seedA_correct' '#print axioms X86Min.SeedA.seedA_refuses' \
    '#print axioms X86Min.SeedB.seedB_correct' '#print axioms X86Min.SeedB.seedB_refuses' \
    '#print axioms X86Uni.seedA_uni_correct' '#print axioms X86Uni.seedA_uni_refuses' \
    '#print axioms X86Uni.seedB_uni_correct' '#print axioms X86Uni.seedB_uni_refuses' \
    '#print axioms X86Uni.seedA_uni_prun' '#print axioms X86Uni.seedB_uni_prun' \
    '#print axioms X86Uni.seedA_uni_refuses_prun' '#print axioms X86Uni.seedB_uni_refuses_prun' > "$work/axioms.lean"
  "$lean" "$work/axioms.lean" > "$work/axioms.log" 2>&1 || fail=1
  cat "$work/axioms.log"
  [ "$(grep -c "depends on axioms: \[propext, Classical.choice, Quot.sound\]" "$work/axioms.log")" = 12 ] \
    || { echo "a theorem about every listing rests on another axiom"; fail=1; }
fi

# The checked theorems must state what they are named for.
for p in "${proofs[@]}"; do
  set -- $p
  grep -qx "theorem X86Min.$1 : exec [0-9]* $2 $3 = Outcome.exit 0 $4 := by" "$work/$1.lean" \
    || { echo "statement of $1 is not exec $2 $3 = exit 0 $4"; fail=1; }
done
[ "$fail" = 0 ] && echo "SEED_PROOFS_OK" || { echo "SEED_PROOFS_FAIL"; exit 1; }
